(def expected
  (get measured r0/bindgen-target))

(defn- check [name layout-var]
  (when-let [{:keys [size+align fields]} (get expected name)]
    (let [layout @layout-var]
      (is (= size+align [(ffi/sizeof layout) (ffi/alignof layout)]) (str name " size/align"))
      (doseq [[path off] fields]
        (is (= off (ffi/field-offset layout (mapv keyword (str/split path #"\."))))
            (str name "." path))))))

